package sqlcheck

import (
	"errors"
	"strings"

	"github.com/0xJean/tabula/internal/pgstmt"
)

// The zero-row description runs in a read-only transaction. Remove only the
// trailing clause generated by a registered row lock. The original PREPARE
// and EXPLAIN still check the complete statement under the workload role.
func lockProjectionQuery(query string) (string, error) {
	tokens, err := pgstmt.ScanFragment(query)
	if err != nil {
		return "", err
	}
	word := func(i int, value string) bool {
		return i >= 0 && i < len(tokens) && tokens[i].Kind == pgstmt.Word && tokens[i].Text == value
	}
	end := len(tokens)
	if word(end-1, "nowait") {
		end--
	} else if word(end-2, "skip") && word(end-1, "locked") {
		end -= 2
	}
	of := end - 2
	invalid := errors.New("expected a registered trailing row-lock clause with a quoted target")
	if !word(0, "select") || !word(of, "of") || tokens[end-1].Kind != pgstmt.Quoted {
		return "", invalid
	}
	var start int
	switch {
	case word(of-2, "for") && (word(of-1, "update") || word(of-1, "share")):
		start = of - 2
	case word(of-3, "for") && word(of-2, "key") && word(of-1, "share"):
		start = of - 3
	case word(of-4, "for") && word(of-3, "no") && word(of-2, "key") && word(of-1, "update"):
		start = of - 4
	default:
		return "", invalid
	}
	return strings.TrimSpace(query[:tokens[start].Start]), nil
}
